=== Configurable.cs ===
// -----------------------------------------------------------------------------
// Configurable.cs
// -----------------------------------------------------------------------------
// This file defines the ConfigurableAttribute, the ConfigurableItem abstraction,
// the ConfigurableBinder, and the ConfigurableExtensions that together enable
// declarative configuration of static and instance fields/properties across
// assemblies.
//
// The attribute marks assemblies, types, and members as configurable. The
// ConfigurableItem hierarchy (ConfigurableField, ConfigurableProperty) provides
// a uniform way to discover, inspect, and set values on members via reflection.
// The binder discovers marked members at startup and loads their values from an
// IConfiguration source (e.g., appsettings.json), with support for ${key}
// variable expansion provided by ConfigurationExtensions.
//
// Purpose: provide a flexible mechanism for automatically populating
// configuration fields from a hierarchical source without requiring explicit
// loading code in each assembly. Examples: default timeouts, pixel positions,
// border sizes that are usually hardcoded as constants but may need to be
// overridden via configuration.
//
// Usage Pattern:
// 1. Mark assemblies with [assembly: Configurable("MyApp")]
// 2. Mark types with [Configurable("DatabaseSettings")]
// 3. Mark static or instance fields/properties with [Configurable("Timeout")]
// 4. Create a ConfigurableBinder with your IConfiguration instance
//    → static members across all loaded assemblies are populated automatically
// 5. Call config.BindConfigurable(instance) for instance members
//    → only instance members on that object are populated
// 6. Values are loaded using hierarchical keys like:
//    "MyApp:DatabaseSettings:Timeout"
// -----------------------------------------------------------------------------
using Microsoft.Extensions.Configuration;
using System.Globalization;
using System.Reflection;
namespace Bovis.Interfaces.Configuration;

/// <summary>
/// Marks assemblies, types, or fields/properties as configurable, enabling automatic
/// loading of values from configuration sources.
/// </summary>
/// <remarks>
/// <para>
/// This attribute can be applied at three levels to create a hierarchical configuration key:
/// </para>
/// <list type="bullet">
/// <item><description><b>Assembly level:</b> Provides a top-level namespace for all configuration in the assembly</description></item>
/// <item><description><b>Type level:</b> Groups related configuration fields/properties together (required if members are marked)</description></item>
/// <item><description><b>Field/Property level:</b> Marks individual static or instance fields/properties to be loaded from configuration</description></item>
/// </list>
/// <para>
/// The final configuration key is constructed as: <c>[AssemblyName]:[TypeName]:[MemberName]</c>
/// where each component uses the Name specified in the attribute, or defaults to the actual name if empty.
/// </para>
/// <example>
/// <code>
/// // In AssemblyInfo.cs
/// [assembly: Configurable("MyApp")]
/// 
/// // In a configuration class
/// [Configurable("Database")]
/// public static class DbConfig
/// {
///     [Configurable("Timeout")]
///     public static int ConnectionTimeout = 30; // Default value (field)
///     
///     [Configurable("MaxRetries")]
///     public static int MaxRetries { get; set; } = 3; // Default value (property)
/// }
/// 
/// // In appsettings.json
/// {
///   "MyApp:Database:Timeout": 60,
///   "MyApp:Database:MaxRetries": 5,
///   /* OR */
///   "MyApp": { "Database": { "Timeout": 60, "MaxRetries": 5 } }    
/// }
/// 
/// // Static members are set when ConfigurableBinder is created.
/// // Instance members are set via: config.BindConfigurable(myInstance);
/// </code>
/// </example>
/// </remarks>
public class ConfigurableAttribute : System.Attribute
{
    /// <summary>
    /// Gets the configuration name for this configurable item.
    /// If empty, the actual member name is used.
    /// </summary>
    public string Name { get; }

    /// <summary>
    /// Initializes a new instance of <see cref="ConfigurableAttribute"/>.
    /// </summary>
    /// <param name="name">
    /// The configuration key name to use. If empty or null, the member's actual name
    /// (assembly name, type name, or field name) will be used as the key.
    /// </param>
    public ConfigurableAttribute(string name = "")
    {
        Name = name;
    }
}

/// <summary>
/// Abstract base class representing a single configurable field or property discovered
/// via reflection. Provides a uniform interface for inspecting metadata, reading/writing
/// values, and converting configuration strings into the appropriate target type.
/// </summary>
/// <remarks>
/// Concrete subclasses are <c>ConfigurableField</c> (wrapping a <see cref="FieldInfo"/>)
/// and <c>ConfigurableProperty</c> (wrapping a <see cref="PropertyInfo"/>).
/// Each item exposes a <see cref="Path"/> that corresponds to the hierarchical
/// configuration key (<c>Assembly:Type:Member</c>) and methods to get, set, or
/// convert values for both static and instance members.
/// </remarks>
public abstract class ConfigurableItem 
{
    /// <summary>
    /// Returns the configuration name from the attribute, falling back to <paramref name="name"/>.
